  "montage.pistes.ajouter_audio_aide": {"fr": "Ajouter une PISTE audio (une bande vide) — posée sous les pistes audio existantes, au-dessus des sous-titres. Bus BRUITAGES, sauf si l'identifiant libre est celui d'une piste historique retirée (A1, A2) : elle revient alors avec son bus d'origine et son habillage.", "en": "Add an audio TRACK (an empty strip) — placed below the existing audio tracks, above the subtitles. SFX bus, unless the free identifier is that of a removed original track (A1, A2): it then comes back with its original bus and look."},
  "montage.pistes.ajouter_audio_aria": {"fr": "Ajouter une piste audio", "en": "Add an audio track"},
  "montage.pistes.ajouter_video": {"fr": "+ piste vidéo", "en": "+ video track"},
  "montage.pistes.ajouter_video_aide": {"fr": "Ajouter une PISTE vidéo plein cadre (une bande vide) — posée tout en haut ; ses plans recouvrent V1 pendant leur durée. Pour poser un clip, c'est « Bibliothèque… ».", "en": "Add a full-frame video TRACK (an empty strip) — placed at the very top; its clips cover V1 for their duration. To place a clip, use “Library…”."},
  "montage.pistes.ajouter_video_aria": {"fr": "Ajouter une piste vidéo plein cadre", "en": "Add a full-frame video track"},
  "montage.pistes.biblio_aide": {"fr": "Ouvrir la Bibliothèque et poser une vidéo, une image ou un rendu sur la piste {piste}, à la tête de lecture — c'est la piste vidéo la plus haute du projet.", "en": "Open the Library and place a video, an image or a render on track {piste}, at the playhead — it is the project's topmost video track."},
  "montage.pistes.biblio_aria": {"fr": "Ouvrir la Bibliothèque pour ajouter un clip", "en": "Open the Library to add a clip"},
