  "montage.texte.aucune_hesitation_un": {"fr": "Aucune hésitation. Les {n} mot souligné sont des mots PLEINS : à couper à la sélection, en les lisant.", "en": "No hesitation. The {n} underlined word is a FULL word: cut it with the selection, reading it."},
  "montage.texte.couper": {"fr": "couper la sélection", "en": "cut the selection"},
  "montage.texte.couper_aide": {"fr": "Couper de {a} s à {b} s sur toutes les pistes non verrouillées : ce qui suit remonte. Annuler défait la coupe entièrement. La durée du projet ne bouge pas : la fin de la timeline est maintenant vide, raccourcissez-la si vous voulez.", "en": "Cut from {a} s to {b} s on all unlocked tracks: what follows moves up. Undo reverts the cut entirely. The project duration does not change: the end of the timeline is now empty, shorten it if you like."},
  "montage.texte.coupes_plusieurs": {"fr": "{n} coupes — {s} s retirés. Annuler défait la coupe entièrement. La durée du projet ne bouge pas : la fin de la timeline est maintenant vide, raccourcissez-la si vous voulez.", "en": "{n} cuts — {s} s removed. Undo reverts the whole cut. The project length does not change: the end of the timeline is now empty, shorten it if you like."},
  "montage.texte.coupes_un": {"fr": "{n} coupe — {s} s retirés. Annuler défait la coupe entièrement. La durée du projet ne bouge pas : la fin de la timeline est maintenant vide, raccourcissez-la si vous voulez.", "en": "{n} cut — {s} s removed. Undo reverts the whole cut. The project length does not change: the end of the timeline is now empty, shorten it if you like."},
