  "subs.cout.aucun_moteur": {"fr": "Aucun moteur de transcription configuré : le coût ne peut pas être annoncé, donc le geste n'est pas offert.", "en": "No transcription engine configured: the cost can't be announced, so the action isn't offered."},
  "subs.cout.aucune_cle": {"fr": "Aucune clé de transcription configurée (Réglages : ElevenLabs ou OpenAI). Le calage d'un texte de narration reste gratuit.", "en": "No transcription key configured (Settings: ElevenLabs or OpenAI). Aligning a narration text stays free."},
  "subs.cout.detectee_moteur": {"fr": "détectée par le moteur", "en": "detected by the engine"},
  "subs.cout.gratuit_apres": {"fr": "Le texte de narration est déjà écrit : le moteur le CALE sur les silences réels du son (langue {langue}). Aucun appel payant, aucun nom propre écorché, et ça marche hors ligne.", "en": "The narration text is already written: the engine ALIGNS it to the real silences of the audio (language {langue}). No paid call, no mangled proper names, and it works offline."},
  "subs.cout.gratuit_pastille": {"fr": "{langue} · calage local · gratuit", "en": "{langue} · local alignment · free"},
