  "subs.cout.moteur_muet": {"fr": "Le moteur ne répond pas : le coût ne peut pas être annoncé, donc rien n'est lancé.", "en": "The engine isn't responding: the cost can't be announced, so nothing is started."},
  "subs.cout.moteur_transcription": {"fr": "moteur de transcription", "en": "transcription engine"},
  "subs.cout.payant_apres": {"fr": "Appel PAYANT à {moteur}{modele}, langue {langue} : {prix} pour {duree} s de son ({tarif} la minute annoncés par le moteur × {duree} ÷ 60), {attente} d'attente ({mise} s de mise en route + {rt} s par seconde de son).", "en": "PAID call to {moteur}{modele}, language {langue}: {prix} for {duree} s of audio ({tarif} per minute announced by the engine × {duree} ÷ 60), {attente} wait ({mise} s startup + {rt} s per second of audio)."},
  "subs.couverture.plan_n": {"fr": "plan {n}", "en": "shot {n}"},
