  "subs.cov.acquittes_hors": {"fr": "{n} acquittés (hors du calcul, muets quand même)", "en": "{n} acknowledged (out of the calculation, silent all the same)"},
  "subs.cov.deplier_title": {"fr": "Déplier les gestes plan par plan : transcrire, écrire une réplique, ou acquitter. Le constat au-dessus ne bouge pas.", "en": "Expand the actions clip by clip: transcribe, write a line, or acknowledge. The finding above doesn't move."},
  "subs.cov.ign_liste_plusieurs": {"fr": "{n} plans acquittés ({liste})", "en": "{n} clips acknowledged ({liste})"},
  "subs.cov.ign_liste_un": {"fr": "{n} plan acquitté ({liste})", "en": "{n} clip acknowledged ({liste})"},
  "subs.cov.ign_plusieurs": {"fr": "{n} plans sortiront muets : acquittés « sans parole ». L'acquittement les a retirés du CALCUL, pas du montage.", "en": "{n} clips will come out silent: acknowledged “no speech”. The acknowledgement removed them from the CALCULATION, not from the edit."},
  "subs.cov.ign_title_plusieurs": {"fr": "{n} plans acquittés « sans parole » : {dur} s RETIRÉS du total {total} s — jamais comptés couverts. Le fichier livré n'a pas changé : ces plans sortiront muets exactement comme avant l'acquittement.", "en": "{n} clips acknowledged “no speech”: {dur} s REMOVED from the {total} s total — never counted as covered. The delivered file hasn't changed: these clips will come out silent exactly as before the acknowledgement."},
  "subs.cov.ign_title_un": {"fr": "{n} plan acquitté « sans parole » : {dur} s RETIRÉS du total {total} s — jamais comptés couverts. Le fichier livré n'a pas changé : ce plan sortira muet exactement comme avant l'acquittement.", "en": "{n} clip acknowledged “no speech”: {dur} s REMOVED from the {total} s total — never counted as covered. The delivered file hasn't changed: this clip will come out silent exactly as before the acknowledgement."},
  "subs.cov.ign_un": {"fr": "{n} plan sortira muet : acquitté « sans parole ». L'acquittement l' a retiré du CALCUL, pas du montage.", "en": "{n} clip will come out silent: acknowledged “no speech”. The acknowledgement removed it from the CALCULATION, not from the edit."},
  "subs.cov.leg_ack": {"fr": "acquitte : n'écrit rien, trace révocable", "en": "acknowledges: writes nothing, reversible trace"},
  "subs.cov.leg_ack_title": {"fr": "Un acquittement n'écrit rien : le plan sortira muet, exactement comme maintenant. Il est RETIRÉ DU TOTAL — il n'est jamais compté comme couvert — donc le pourcentage monte sans qu'une réplique soit née, et la ligne des comptes garde « plans acquittés ». Révocable.", "en": "An acknowledgement writes nothing: the clip will come out silent, exactly as now. It is REMOVED FROM THE TOTAL — it is never counted as covered — so the percentage goes up without a line being created, and the counts row keeps “acknowledged clips”. Reversible."},
  "subs.cov.leg_fix": {"fr": "écrit dans le fichier livré", "en": "writes into the delivered file"},
  "subs.cov.leg_fix_title": {"fr": "Un correctif écrit des répliques sur le plan : la couverture monte parce que la vidéo change. Une réplique VIDE, elle, ne couvre rien tant qu'elle n'a pas de texte.", "en": "A fix writes lines on the clip: coverage goes up because the video changes. An EMPTY line, however, covers nothing until it has text."},
  "subs.cov.muets_total": {"fr": "{n} plans du montage sortiront muets", "en": "{n} clips of the edit will come out silent"},
  "subs.cov.note_title": {"fr": "Couvert = secondes recouvertes par des répliques VISIBLES et NON VIDES. Total = somme des durées des {plans} à sous-titrer. Les deux nombres sont arrondis au dixième AVANT la division : refaire le calcul redonne ce pourcentage.", "en": "Covered = seconds covered by VISIBLE, NON-EMPTY lines. Total = sum of the durations of the {plans} to subtitle. Both numbers are rounded to the tenth BEFORE the division: redoing the calculation gives this percentage back."},
  "subs.cov.note_title_ign_plusieurs": {"fr": "Couvert = secondes recouvertes par des répliques VISIBLES et NON VIDES. Total = somme des durées des {plans} à sous-titrer, les {n} plans acquittés « sans parole » RETIRÉS du total (pas ajoutés au couvert). Les deux nombres sont arrondis au dixième AVANT la division : refaire le calcul redonne ce pourcentage.", "en": "Covered = seconds covered by VISIBLE, NON-EMPTY lines. Total = sum of the durations of the {plans} to subtitle, the {n} clips acknowledged “no speech” REMOVED from the total (not added to the covered part). Both numbers are rounded to the tenth BEFORE the division: redoing the calculation gives this percentage back."},
  "subs.cov.note_title_ign_un": {"fr": "Couvert = secondes recouvertes par des répliques VISIBLES et NON VIDES. Total = somme des durées des {plans} à sous-titrer, les {n} plan acquitté « sans parole » RETIRÉS du total (pas ajoutés au couvert). Les deux nombres sont arrondis au dixième AVANT la division : refaire le calcul redonne ce pourcentage.", "en": "Covered = seconds covered by VISIBLE, NON-EMPTY lines. Total = sum of the durations of the {plans} to subtitle, the {n} clip acknowledged “no speech” REMOVED from the total (not added to the covered part). Both numbers are rounded to the tenth BEFORE the division: redoing the calculation gives this percentage back."},
