  "subs.plan.decale_suivants": {"fr": "Décale les {n} sous-titres suivants de {ms}. Leur texte ne suivra plus la voix — à ne faire que si le montage suit.", "en": "Shifts the {n} following subtitles by {ms}. Their text will no longer follow the voice — only do this if the edit follows."},
  "subs.plan.decaler_sortirait": {"fr": "Décaler les suivants sortirait le dernier sous-titre de la vidéo ({trop} de trop).", "en": "Shifting the following ones would push the last subtitle past the end of the video ({trop} over)."},
  "subs.plan.decouper_effet": {"fr": "Le segment devient {n} sous-titres ({durs}), coupés sur les mots avec {ms} de respiration entre eux. Les voisins ne bougent pas.", "en": "The segment becomes {n} subtitles ({durs}), cut on words with {ms} of breathing room between them. The neighbors do not move."},
